/* Real, local Git lab: controller and engine stay outside the core bundle. */
let gitCourseApp=null,gitCoursePromise=null;
function gitCourseLoad(){return gitCoursePromise||(gitCoursePromise=import(new URL('./runtime/git-course.js',document.baseURI).href).then(module=>{gitCourseApp=module.createGitCourse({state:()=>state,route:()=>aRoute,esc,fetch:aFetch,persist:aPersist,render:()=>render(),navigate:aGo,choiceOrder:(values,key)=>academyChoiceOrder(values,key,state.profile.id)})}).catch(error=>{gitCoursePromise=null;throw error}))}
const gitResolvePrevious=aResolve;aResolve=async function(){const route=academyRoute(location.hash);if(route.kind!=='apprendre'||route.id!=='git-bases')return gitResolvePrevious();const generation=++aGeneration;++currGeneration;currStop();aRoute=route;aLoading=true;aError=false;render();try{await gitCourseLoad();await gitCourseApp.resolve(route);if(generation!==aGeneration)return;aLoading=false;render();$('#main')?.focus({preventScroll:true})}catch{if(generation!==aGeneration)return;aLoading=false;aError=true;render()}};
const gitViewPrevious=currView;currView=function(){return aRoute.kind==='apprendre'&&aRoute.id==='git-bases'?aError?'<section class="a-empty"><h1>Le cours Git ne s’ouvre pas</h1><p>Connecte-toi une première fois ou utilise une version déjà enregistrée.</p><a class="primary" href="#/apprendre/git-bases">Réessayer</a></section>':gitCourseApp?gitCourseApp.view():aLibWait():gitViewPrevious()};
const gitHubPrevious=currHub;currHub=function(){return gitHubPrevious()+`<section class="curr-entry"><div><span class="eyebrow">OUTIL · DÉBUTANT · VRAI DÉPÔT LOCAL</span><h2>Git et GitHub : versionner et collaborer</h2><p>12 leçons, des fichiers, commits et branches dans ton navigateur. GitHub est une extension en ligne, sans publication simulée.</p></div><a class="primary" href="#/apprendre/git-bases">Voir le programme →</a></section>`};
const gitProgressPrevious=progressView;progressView=function(){const done=Object.values(state.git?.completed||{}).filter(Boolean).length;return (done||state.git?.last?`<section class="panel"><h2>Git et GitHub</h2><p>${done}/12 leçons validées.</p><a class="primary" href="#/apprendre/git-bases">Retrouver mon atelier Git →</a></section>`:'')+gitProgressPrevious()};
const gitSavedPrevious=aSavedBundles;aSavedBundles=function(){return (state.git?.saved?'<section class="panel"><h2>Git et GitHub · cours enregistré</h2><p>Les fichiers et commits de l’atelier restent dans le stockage local de ce navigateur.</p><a class="primary" href="#/apprendre/git-bases">Ouvrir l’atelier Git →</a></section>':'')+gitSavedPrevious()};
